const fresh=()=>({wordRotation:{},lastWords:{},savedGames:[],profile:null,history:[],gamesStarted:0,coins:0,unlockedThemes:['classic'],unlockedAvatars:['🧭'],avatar:'🧭',gridTheme:'classic',achievements:[],daily:{lastDate:null,currentStreak:0,bestStreak:0,rewardDates:[]},settings:{light:true,hiddenTimer:false},starterGiftClaimed:false});
function load(){try{const x=JSON.parse(localStorage.getItem(KEY)||'null');if(!x||typeof x!=='object')return fresh();const s=fresh();return{...s,...x,savedGame:null,wordRotation:x.wordRotation&&typeof x.wordRotation==='object'&&!Array.isArray(x.wordRotation)?Object.fromEntries(Object.entries(x.wordRotation).filter(([,v])=>Array.isArray(v)).map(([k,v])=>[k,v.filter(w=>typeof w==='string')])):{},lastWords:x.lastWords&&typeof x.lastWords==='object'&&!Array.isArray(x.lastWords)?Object.fromEntries(Object.entries(x.lastWords).filter(([,v])=>Array.isArray(v)).map(([k,v])=>[k,v.filter(w=>typeof w==='string')])):{},savedGames:(Array.isArray(x.savedGames)?x.savedGames:(x.savedGame?[x.savedGame]:[])).filter(g=>g&&typeof g.id==='string'&&Array.isArray(g.grid)&&Array.isArray(g.placements)&&Array.isArray(g.words)),profile:x.profile&&typeof x.profile.name==='string'?x.profile:null,history:Array.isArray(x.history)?x.history.filter(r=>r&&typeof r.id==='string'&&Number.isFinite(r.score)):[],unlockedThemes:Array.isArray(x.unlockedThemes)?x.unlockedThemes:['classic'],unlockedAvatars:Array.isArray(x.unlockedAvatars)?x.unlockedAvatars:['🧭'],achievements:Array.isArray(x.achievements)?x.achievements:[],daily:{...s.daily,...x.daily,rewardDates:Array.isArray(x.daily?.rewardDates)?x.daily.rewardDates:[]},settings:{...s.settings,...x.settings},coins:Math.max(0,Number(x.coins)||0),gamesStarted:Math.max(0,Number(x.gamesStarted)||0)}}catch{return fresh()}}
let data=load(),game=null,timer=null,filter='all',sort='score',toastTimer,pointerStart=null,pointerDown=false,preview=[];
